export function TableFixedIdLo(b, i) { return TableFixedGetU32(b.bytes, b.at + TableFixedLayoutHeaderBytes + i * TableFixedEntryBytes); }
export function TableFixedIdHi(b, i) { return TableFixedGetU32(b.bytes, b.at + 8 + i * TableFixedEntryBytes); }
export function TableFixedKind(b, i) { return b.bytes[b.at + TableFixedLayoutHeaderBytes + i * TableFixedEntryBytes + 8]; }
export function TableFixedSize(b, i) { return TableFixedGetU32(b.bytes, b.at + TableFixedLayoutHeaderBytes + i * TableFixedEntryBytes + 9); }
export function TableFixedChildren(b, i) { return TableFixedGetU32(b.bytes, b.at + TableFixedLayoutHeaderBytes + i * TableFixedEntryBytes + 13); }

function TableFixedSameId(a, ai, b, bi) {
  return TableFixedIdLo(a, ai) === TableFixedIdLo(b, bi) && TableFixedIdHi(a, ai) === TableFixedIdHi(b, bi);
}

// TableFixedSubtree is how many entries the subtree rooted at i occupies, so a
// walk steps over a child it does not want without knowing what is in it.
// THIS IS WHAT MAKES SKIPPING FREE: an unknown field, and an unknown NESTED
// TYPE, are stepped over by the size their entry states. ITERATIVE ON PURPOSE:
// a layout is a stranger's bytes, so a chain of single-child entries is a
// stack depth the wire gets to choose; this walk gives it none. It is only
// ever called on a layout that has already passed every rule below, so the
// tree closes.
export function TableFixedSubtree(b, i) {
  if (i < 0 || i >= b.count) { return 1; }
  let pending = 1, n = 0, at = i;
  while (pending > 0 && at < b.count) {
    pending--;
    n++;
    pending += TableFixedChildren(b, at);
    at++;
    if (pending > b.count) { break; }
  }
  return n;
}

function TableFixedUnionArmBytes(b, i) {
  const children = TableFixedChildren(b, i);
  let widest = 0, at = i + 1;
  for (let k = 0; k < children; k++) {
    const s = TableFixedSize(b, at);
    if (s > widest) { widest = s; }
    at += TableFixedSubtree(b, at);
  }
  return widest;
}

function TableFixedTagBytes(b, i) { return TableFixedSize(b, i) - TableFixedUnionArmBytes(b, i); }

// ---- THE LAYOUT'S OWN VALIDATION, RULE BY NAMED RULE -----------------------
//
// A LAYOUT ARRIVES FROM AN UNTRUSTED PEER and it is the one structure a reader
// must parse before it knows anything at all, so every rule below runs BEFORE
// a single record byte is touched and each refuses under its OWN NAME rather
// than under one word for all of them (docs/SPEC-TABLES.md §3.4,
// docs/FIXED-FORM-ALGORITHM.md §1.1).
//
// A KIND THIS BUILD DOES NOT KNOW IS A REFUSAL, and that is a ruling rather
// than an oversight. A FIXED FORM HAS A CLOSED KIND SET: the form byte versions
// everything behind it, kinds included, so a layout carrying a kind outside the
// set is not a newer layout of THIS form — it is a layout of a form whose byte
// this reader never saw, and there is no version of "step over it" that is
// honest about that. layout_kind_unknown says exactly what happened, and the
// peer is told to speak this form or a form this reader carries.
//
// NOR IS THERE A CYCLE RULE, because a pre-order walk cannot express a cycle:
// an entry's children ARE THE ENTRIES THAT FOLLOW IT, so a child's index is
// always higher than its parent's, the layout is finite, and there is no back
// reference for a cycle to be made of. The tree-closure rule is what bounds
// the walk, and the depth rule is what bounds the reader's stack.

function TableFixedFail(b, why) {
  if (b.refusal === TableFixedRefusal.None) { b.refusal = why; }
}

// A LEAF KIND'S ADMITTED SIZES. Kind and size fix each other on this wire with
// ONE exception, and it is stated here rather than left to be found: a
// bits(N) field rides at its DECLARED STORAGE WIDTH — four bytes for N <= 32 and
// eight above (§3.4) — under the unsigned integer kind its BIT COUNT picks
// (§3), so kinds 6 and 7 admit four as well as their own width.
// Answers 1 if leaf and size ok, 0 if leaf and size bad, -1 if not a leaf.
function TableFixedLeafSize(kind, size) {
  switch (kind) {
    case 1:  return size === 1 ? 1 : 0;                 // bool
    case 2:  return size === 1 ? 1 : 0;                 // i8
    case 3:  return size === 2 ? 1 : 0;                 // i16
    case 4:  return size === 4 ? 1 : 0;                 // i32
    case 5:  return size === 8 ? 1 : 0;                 // i64
    case 6:  return size === 1 || size === 4 ? 1 : 0;   // u8,  and bits( 1 .. 8 )
    case 7:  return size === 2 || size === 4 ? 1 : 0;   // u16, and bits( 9 .. 16 )
    case 8:  return size === 4 ? 1 : 0;                 // u32, and bits( 17 .. 32 )
    case 9:  return size === 8 ? 1 : 0;                 // u64, flags, and bits( 33 .. 64 )
    case 10: return size === 4 ? 1 : 0;                 // f32
    case 11: return size === 8 ? 1 : 0;                 // f64
    case 17: return size === 4 ? 1 : 0;                 // a pointer index, which no fixed table carries
    case 18: case 19: return size === 16 ? 1 : 0;       // i128, u128
    case 20: case 25: return size === 1 ? 1 : 0;        // fixed8, ufixed8
    case 21: case 26: return size === 2 ? 1 : 0;
    case 22: case 27: return size === 4 ? 1 : 0;
    case 23: case 28: return size === 8 ? 1 : 0;
    case 24: case 29: return size === 16 ? 1 : 0;
    case 32: return size === 0 ? 1 : 0;                 // a variant, and an arm that holds nothing
  }
  return -1;
}

function TableFixedOrdinalWidth(n) { return n === 1 || n === 2 || n === 4 || n === 8; }

// THE CLOSED KIND SET (docs/SPEC-TABLES.md §3, §3.4): §3's own kinds 1..30,
// the no-payload variant 32, wstring 33, and the ONE kind this form's layout
// adds, the optional wrapper 35. 31 is §3's BODY framing escape and 34 is
// reserved: neither is a kind a declaration spells, so neither is ever an
// entry's kind. A KIND OUTSIDE THIS SET IS A REFUSAL, not a leaf to step over.
function TableFixedKnownKind(kind) {
  if (kind >= 1 && kind <= 30) { return true; }
  return kind === 32 || kind === 33 || kind === 35;
}

function TableFixedClearView(out) {
  out.bytes = null;
  out.at = 0;
  out.count = 0;
}

// TableFixedCheckEntry validates the subtree rooted at i and answers how many
// entries it occupies, which is the same arithmetic TableFixedSubtree does and
// is why that walk is safe to run afterwards and only afterwards.
function TableFixedCheckEntry(b, i, depth) {
  if (b.refusal !== TableFixedRefusal.None) { return 0; }
  if (i < 0 || i >= b.count) { TableFixedFail(b, TableFixedRefusal.LayoutTreeUnclosed); return 0; }
  if (depth > TableFixedMaxDepth) { TableFixedFail(b, TableFixedRefusal.LayoutTooDeep); return 0; }
  const kind = TableFixedKind(b, i);
  const size = TableFixedSize(b, i);
  // THE CLOSED KIND SET, FIRST: a kind outside it is a layout of another form
  // and is refused whole, never walked and never stepped over.
  if (!TableFixedKnownKind(kind)) { TableFixedFail(b, TableFixedRefusal.LayoutKindUnknown); return 0; }
  if (size > TableFixedRecordMaxBytes) { TableFixedFail(b, TableFixedRefusal.LayoutRecordTooLarge); return 0; }

  // THE CHILDREN FIRST, in the pre-order the layout is written in.
  const kids = TableFixedChildren(b, i);
  let at = i + 1;
  let sum = 0;
  let widest = 0;
  let firstSize = 0, secondSize = 0, firstKind = 0, firstChildren = 0;
  let kidsAreVariants = true;
  for (let k = 0; k < kids; k++) {
    const child = at;
    const used = TableFixedCheckEntry(b, child, depth + 1);
    if (b.refusal !== TableFixedRefusal.None) { return 0; }
    const childSize = TableFixedSize(b, child);
    if (k === 0) {
      firstSize = childSize;
      firstKind = TableFixedKind(b, child);
      firstChildren = TableFixedChildren(b, child);
    }
    if (k === 1) { secondSize = childSize; }
    if (TableFixedKind(b, child) !== 32) { kidsAreVariants = false; }
    sum += childSize;
    if (childSize > widest) { widest = childSize; }
    if (sum > TableFixedRecordMaxBytes) { TableFixedFail(b, TableFixedRefusal.LayoutRecordTooLarge); return 0; }
    at += used;
  }

  const leaf = TableFixedLeafSize(kind, size);
  if (leaf === 0) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
  if (leaf === 1) {
    if (kids !== 0) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
    return at - i;
  }
  switch (kind) {
    case 13: { // a TABLE: its size is the SUM of its fields'
      if (size !== sum) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    case 35: { // the OPTIONAL WRAPPER: one child, one present byte in front of it
      if (kids !== 1) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (size !== sum + 1) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    case 14: { // an ARRAY: a whole number of elements, behind a count or not
      if (kids !== 1) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (firstSize === 0) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      const bare = (size % firstSize) === 0;
      const counted = size >= 4 && ((size - 4) % firstSize) === 0;
      if (!bare && !counted) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    case 16: { // an ENUM-KEYED array: the KEY ENUM then the ELEMENT, every slot written
      if (kids !== 2) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (firstKind !== 30) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (secondSize === 0 || (size % secondSize) !== 0) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      // AT LEAST one slot per variant. Not exactly one: an enum widened
      // by an explicit max has more slots than it has names, and the
      // layout carries only the names.
      if (((size / secondSize) | 0) < firstChildren) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    case 15: { // a UNION: the TAG at its own width, then the WIDEST ARM
      if (kids === 0) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (size <= widest) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      if (!TableFixedOrdinalWidth(size - widest)) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    case 30: { // an ENUM: the ordinal's storage width, and its children are VARIANTS
      if (!TableFixedOrdinalWidth(size)) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      if (kids !== 0 && !kidsAreVariants) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      break;
    }
    case 12: { // string(N): the length, then N bytes
      if (kids !== 0) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (size < 4) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    case 33: { // wstring(N): the length in CODE UNITS, then 2N bytes
      if (kids !== 0) { TableFixedFail(b, TableFixedRefusal.LayoutKindInvalid); return 0; }
      if (size < 4 || ((size - 4) % 2) !== 0) { TableFixedFail(b, TableFixedRefusal.LayoutSizeMismatch); return 0; }
      break;
    }
    // Every kind of the closed set is either a leaf above or a case here,
    // so this is unreachable — and it refuses rather than admits, because
    // a kind that reached it is a kind the two lists disagree about.
    default: TableFixedFail(b, TableFixedRefusal.LayoutKindUnknown); return 0;
  }
  return at - i;
}

// TableFixedParseLayout is the WHOLE of what a reader trusts a layout on. It
// answers false and a REASON BY NAME on the view, and the caller reports that
// reason. A layout that fails any rule SETS NOTHING: no plan is compiled, no
// counter moves, and the reader is in the state it was in before the bytes
// arrived.
export function TableFixedParseLayout(bytes, at, length, out) {
  TableFixedClearView(out);
  out.refusal = TableFixedRefusal.None;
  if (bytes === null || length < TableFixedLayoutHeaderBytes) {
    out.refusal = TableFixedRefusal.LayoutMalformed;
    return false;
  }
  // 1. THE ENTRY COUNT FITS THE LAYOUT LENGTH EXACTLY
  const count = TableFixedGetU32(bytes, at);
  if (count === 0 || count * TableFixedEntryBytes + TableFixedLayoutHeaderBytes !== length) {
    out.refusal = TableFixedRefusal.LayoutCountMismatch;
    return false;
  }
  out.bytes = bytes;
  out.at = at;
  out.count = count;
  // 2. THE ROOT IS A TABLE, and its size is the record's body
  if (TableFixedKind(out, 0) !== 13) {
    out.refusal = TableFixedRefusal.LayoutKindInvalid;
    TableFixedClearView(out);
    return false;
  }
  const rootSize = TableFixedSize(out, 0);
  if (rootSize === 0 || rootSize > TableFixedRecordMaxBytes) {
    out.refusal = TableFixedRefusal.LayoutRecordTooLarge;
    TableFixedClearView(out);
    return false;
  }
  // 3. EVERY KIND IN THE CLOSED SET AND USED AS ITS DEFINITION ALLOWS, EVERY
  //    SIZE THE ONE ITS CHILDREN ACCOUNT FOR, NOTHING PAST THE WALK'S BOUND
  const used = TableFixedCheckEntry(out, 0, 0);
  if (out.refusal !== TableFixedRefusal.None) {
    TableFixedClearView(out);
    return false;
  }
  // 4. THE PRE-ORDER WALK CONSUMES EXACTLY THE ENTRIES: the tree closes and
  //    the layout has nothing left over
  if (used !== out.count) {
    out.refusal = TableFixedRefusal.LayoutTreeUnclosed;
    TableFixedClearView(out);
    return false;
  }
  return true;
}

// ---- THE PLAN COMPILER -----------------------------------------------------
//
// The SAME LOOP runs over this plan as over the identity plan. What the
// compiler does, ONCE PER PEER, is what a read would otherwise do once per
// record: map the writer's ids onto this reader's fields; leave a field it
// cannot name OUT of the plan, which is what skips it, by arithmetic that was
// going to step past it anyway; and leave a field the writer does not carry
// out too, which is what defaults it, because the prefill already put the
// declared default there.

// MY SIDE of the layout, five int32 lanes per entry of my own layout: the
// storage facts a layout entry cannot carry. In C++ these are offsetof rows;
// here they are offsets into the canonical image.
const TableFixedDstLanes = 5;
const TableFixedDstOff = 0;
const TableFixedDstStride = 1;
const TableFixedDstAux = 2;
const TableFixedDstCounted = 3;
const TableFixedDstArg = 4;

function TableFixedPush(plan, op, src, dst, size, aux, guard, arg, meta) {
  // THE HALF IS TESTED AT THE PUSH: pass 0 keeps the unguarded entries, pass 1
  // the guarded ones, and the plan states where the second half starts (§4.1).
  if (!TableFixedKeeping(plan, guard)) { return; }
  if (plan.count >= plan.capacity) { plan.overflow = true; return; }
  const b = plan.count * TableFixedLanes;
  const e = plan.entries;
  e[b + TableFixedLaneOp] = op;
  e[b + TableFixedLaneSrc] = src;
  e[b + TableFixedLaneDst] = dst;
  e[b + TableFixedLaneSize] = size;
  e[b + TableFixedLaneAux] = aux;
  e[b + TableFixedLaneGuard] = guard;
  e[b + TableFixedLaneArg] = arg;
  e[b + TableFixedLaneMeta] = meta;
  // argw IS THE GUARD'S WIDTH IN BYTES. Flavour stays in meta. Zero is one.
  let w = plan.argw | 0;
  if (w === 0) { w = 1; }
  e[b + TableFixedLaneArgW] = w;
  plan.count++;
}

// §4'S WIDENING RUNGS, and the fixed form spends no rule of its own on them: a
// kind that GREW since the writer decodes at the writer's width and lands
// exactly, counting one widened. Coming back DOWN the ladder, or across two of
// them, is a kind that MOVED and is reported rather than reinterpreted.
function TableFixedWidens(from, to) {
  if (from >= 6 && from <= 9 && to >= 6 && to <= 9) { return to > from; } // u8 .. u64
  if (from >= 2 && from <= 5 && to >= 2 && to <= 5) { return to > from; } // i8 .. i64
  // THE FIXED-POINT RUNGS, signed 20..24 and unsigned 25..29: a fixed(I,F) into
  // a wider I at equal F is a LADDER widen and not a kind that moved
  // (docs/FIXED-FORM-ALGORITHM.md §1, §5.1).
  if (from >= 20 && from <= 24 && to >= 20 && to <= 24) { return to > from; }
  if (from >= 25 && from <= 29 && to >= 25 && to <= 29) { return to > from; }
  return from === 10 && to === 11;                                        // f32 -> f64
}

// A WIDEN'S SIGN IS THE LADDER'S: the source sign-extends when the WRITER's kind
// is signed — i8..i64 and a SIGNED fixed(I,F), 20..24 — and zero-extends
// otherwise. The SAME-KIND widen has no sign at all and the grown enum ordinal
// none either: both zero-extend (§5.2).
function TableFixedSignedKind(kind) { return (kind >= 2 && kind <= 5) || (kind >= 20 && kind <= 24); }

function TableFixedLayRemap(plan, values, n) {
  const need = n + 1;
  if (plan.remapUsed + need > plan.remap.length) { plan.overflow = true; return 0; }
  const at = plan.remapUsed;
  plan.remap[at] = n;
  for (let i = 0; i < n; i++) { plan.remap[at + 1 + i] = values[i]; }
  plan.remapUsed += need;
  return at;
}

// AN ENUM'S REMAP, BUILT THEN LAID DOWN. The table is AS LONG AS THE WRITER'S
// VARIANT COUNT (§5.2) and not capped at 255: the reference's cap is §5.8 row 14
// and a leg that reproduced it would silently remap a writer's 256th variant to
// None as though the reader did not name it. The scratch grows at COMPILE time,
// which on this leg is module load and off every load path (§5.9 #3).
let TableFixedRemapScratch = new Int32Array(256);
function TableFixedRemapRoom(n) {
  if (n > TableFixedRemapScratch.length) { TableFixedRemapScratch = new Int32Array(n); }
  return TableFixedRemapScratch;
}

// THE ONE DEAD REPORT. The census — unknown and kindMismatch — is once per
// field PER PEER and never per array element or per keyed slot (§5.4, §5.8 row
// 11, §5.9 #43). The entries still have to be laid down for every element, so
// the repeats walk the same pairs into a report NOBODY READS. It is module-level
// because the compile must not allocate per element, and it is never reset
// because nothing ever looks at it.
const TableFixedQuietCensus = new TableFixedReport();

// matchChildren walks a TABLE's children on both sides, by id.
function TableFixedMatchChildren(plan, theirs, ti, theirAt, mine, mi, dst, myAt, guard, arg, report) {
  const theirChildren = TableFixedChildren(theirs, ti);
  const myChildren = TableFixedChildren(mine, mi);
  let myChild = mi + 1;
  for (let k = 0; k < myChildren; k++) {
    let theirChild = ti + 1;
    let theirOff = theirAt;
    for (let j = 0; j < theirChildren; j++) {
      if (TableFixedSameId(theirs, theirChild, mine, myChild)) {
        TableFixedCompileEntry(plan, theirs, theirChild, theirOff, mine, myChild, dst, myAt, guard, arg, report);
        break;
      }
      theirOff += TableFixedSize(theirs, theirChild);
      theirChild += TableFixedSubtree(theirs, theirChild);
    }
    myChild += TableFixedSubtree(mine, myChild);
  }
  // EVERY FIELD OF THEIRS I COULD NOT NAME IS ONE unknown
  let tcAt = ti + 1;
  for (let j = 0; j < theirChildren; j++) {
    let named = false;
    let mcAt = mi + 1;
    for (let k = 0; k < myChildren; k++) {
      if (TableFixedSameId(mine, mcAt, theirs, tcAt)) { named = true; break; }
      mcAt += TableFixedSubtree(mine, mcAt);
    }
    if (!named) { report.unknown++; }
    tcAt += TableFixedSubtree(theirs, tcAt);
  }
}

// THE TWO-PASS SPLIT (§5.2): the walk runs twice, UNGUARDED first, and each pass
// drops the entries that are not its half. A kind that ALLOCATES from the pool
// BEFORE it pushes — the enum, whose remap table is laid down — must test the
// half FIRST, or the discarded pass still spends the pool and a plan that fits
// comes back plan_too_large.
function TableFixedKeeping(plan, guard) {
  return plan.pass === 0 ? guard === TableFixedNoGuard : guard !== TableFixedNoGuard;
}

function TableFixedCompileEntry(plan, theirs, ti, theirAt, mine, mi, dst, myAt, guard, arg, report) {
  const theirKind = TableFixedKind(theirs, ti);
  const myKind = TableFixedKind(mine, mi);
  const theirSize = TableFixedSize(theirs, ti);
  const mySize = TableFixedSize(mine, mi);
  const row = mi * TableFixedDstLanes;
  const at = myAt + dst[row + TableFixedDstOff];
  const auxAt = myAt + dst[row + TableFixedDstAux];
  // T INTO ?T (§5.2 EMIT, bill §12.8): the reader wrapped a value the writer
  // carried bare. The PRESENT byte is a CONSTANT 1 at the wrapper's aux lane,
  // constant in its VALUE and still carrying the row's own guard/arg (§5.9 #13),
  // and the payload is compiled against the writer's own entry under the same
  // guard and ordinal. It is not a kind that moved.
  if (myKind === 35 && theirKind !== 35) {
    TableFixedPush(plan, TableFixedOpConst, theirAt, auxAt, 1, 1, guard, arg, 0);
    TableFixedCompileEntry(plan, theirs, ti, theirAt, mine, mi + 1, dst, myAt, guard, arg, report);
    return;
  }
  if (theirKind !== myKind) {
    if (TableFixedWidens(theirKind, myKind)) {
      const op = theirKind === 10 ? TableFixedOpWidenF : TableFixedOpWiden;
      TableFixedPush(plan, op, theirAt, at, theirSize, 0, guard, arg,
        (mySize & 0xff) | (TableFixedSignedKind(theirKind) ? 0x100 : 0));
      return;
    }
    // A KIND THAT MOVED IS REPORTED AND NEVER REINTERPRETED (§4).
    report.kindMismatch++;
    return;
  }
  switch (myKind) {
    case 35: { // the OPTIONAL wrapper: the present byte, then the payload whole
      TableFixedPush(plan, TableFixedOpCopy, theirAt, auxAt, 1, 0, guard, arg, 0);
      TableFixedCompileEntry(plan, theirs, ti + 1, theirAt + 1, mine, mi + 1, dst, myAt, guard, arg, report);
      break;
    }
    case 13: { // a nested table: match its fields
      TableFixedMatchChildren(plan, theirs, ti, theirAt, mine, mi, dst, at, guard, arg, report);
      break;
    }
    case 14: { // an array: the count, then min( their bound, my bound ) elements
      const theirElem = TableFixedSize(theirs, ti + 1);
      const myElem = TableFixedSize(mine, mi + 1);
      const head = dst[row + TableFixedDstCounted] ? 4 : 0;
      const theirN = theirElem ? ((theirSize - head) / theirElem) | 0 : 0;
      const myN = myElem ? ((mySize - head) / myElem) | 0 : 0;
      if (dst[row + TableFixedDstCounted]) {
        // THE BOUND IS THE WRITER'S their_n AND NOT THE READER'S (§5.2 EMIT,
        // bill §12.5): a count forged past what THAT peer could have written
        // clamps and counts, and a reader whose own bound merely grew does not
        // let the forgery through. The reader's storage has room by §5.1.
        TableFixedPush(plan, TableFixedOpCount, theirAt, auxAt, theirN, 0, guard, arg, 0);
      }
      const theirBase = theirAt + head;
      const n = theirN < myN ? theirN : myN;
      for (let i = 0; i < n; i++) {
        // THE FIRST ELEMENT CARRIES THE CENSUS AND THE REST ARE QUIET: a
        // four-element array of a table with one unknown field is ONE unknown,
        // not four (§5.4, §5.8 row 11).
        TableFixedCompileEntry(plan, theirs, ti + 1, theirBase + i * theirElem,
          mine, mi + 1, dst, at + i * dst[row + TableFixedDstStride], guard, arg,
          i === 0 ? report : TableFixedQuietCensus);
      }
      break;
    }
    case 16: { // an enum-keyed array: every slot, matched by the KEY's id
      const theirKeyChildren = TableFixedChildren(theirs, ti + 1);
      const myKeyChildren = TableFixedChildren(mine, mi + 1);
      const theirElemAt = ti + 1 + TableFixedSubtree(theirs, ti + 1);
      const myElemAt = mi + 1 + TableFixedSubtree(mine, mi + 1);
      const theirElemSize = TableFixedSize(theirs, theirElemAt);
      // THE FIRST MATCHED SLOT CARRIES THE CENSUS, and every slot after it is
      // quiet: a keyed array's slots are one field's storage repeated, so an
      // unknown inside the element is ONE unknown for the peer (§5.4).
      let keyedCounted = false;
      for (let k = 0; k < myKeyChildren; k++) {
        for (let j = 0; j < theirKeyChildren; j++) {
          if (!TableFixedSameId(theirs, ti + 2 + j, mine, mi + 2 + k)) { continue; }
          TableFixedCompileEntry(plan, theirs, theirElemAt, theirAt + j * theirElemSize,
            mine, myElemAt, dst, at + k * dst[row + TableFixedDstStride], guard, arg,
            keyedCounted ? TableFixedQuietCensus : report);
          keyedCounted = true;
          break;
        }
      }
      break;
    }
    case 15: { // a union: the tag, remapped, then each arm matched by id
      const theirTag = TableFixedTagBytes(theirs, ti);
      const myTag = TableFixedTagBytes(mine, mi);
      const savedArgw = plan.argw;
      plan.argw = (theirTag >= 1 && theirTag <= 8) ? theirTag : 1;
      const theirArms = TableFixedChildren(theirs, ti);
      const myArms = TableFixedChildren(mine, mi);
      let myArm = mi + 1;
      for (let k = 0; k < myArms; k++) {
        let theirArm = ti + 1;
        for (let j = 0; j < theirArms; j++) {
          if (TableFixedSameId(theirs, theirArm, mine, myArm)) {
            // MY tag value, written under THEIR tag's guard
            TableFixedPush(plan, TableFixedOpConst, theirAt, auxAt, myTag, k + 1, theirAt, j + 1, 0);
            TableFixedCompileEntry(plan, theirs, theirArm, theirAt + theirTag,
              mine, myArm, dst, at, theirAt, j + 1, report);
            break;
          }
          theirArm += TableFixedSubtree(theirs, theirArm);
        }
        myArm += TableFixedSubtree(mine, myArm);
      }
      plan.argw = savedArgw;
      break;
    }
    case 30: { // an enum: the ordinal is the layout's position, so it remaps
      // A GROWN ORDINAL WIDTH IS A WIDEN, unsigned, and it counts widened (§5.2
      // EMIT kind 30, §5.4, bill §12.7). Only a SAME-WIDTH ordinal takes the
      // remap table.
      if (theirSize < mySize) {
        TableFixedPush(plan, TableFixedOpWiden, theirAt, at, theirSize, 0, guard, arg, mySize & 0xff);
        break;
      }
      // THE POOL IS TESTED BEFORE IT SPENDS (§5.2, the two-pass split).
      if (!TableFixedKeeping(plan, guard)) { break; }
      const theirVariants = TableFixedChildren(theirs, ti);
      const myVariants = TableFixedChildren(mine, mi);
      const n = theirVariants;
      TableFixedRemapRoom(n);
      for (let j = 0; j < n; j++) {
        let landed = 0;
        for (let k = 0; k < myVariants; k++) {
          if (TableFixedSameId(mine, mi + 1 + k, theirs, ti + 1 + j)) { landed = k + 1; break; }
        }
        TableFixedRemapScratch[j] = landed;
      }
      const table = TableFixedLayRemap(plan, TableFixedRemapScratch, n);
      TableFixedPush(plan, TableFixedOpOrdinal, theirAt, at, theirSize, table, guard, arg, mySize & 0xff);
      break;
    }
    case 12: case 33: { // text
      // ARG STAYS THE ARM'S, AND THE FLAVOUR GOES IN META. Writing the flavour
      // into arg was a text field under a union arm losing its guard value: the
      // read loop would then compare the writer's TAG BYTE against a text
      // flavour, so the entry either never ran under its own arm or ran under
      // somebody else's and smeared its bytes across a sibling's storage. The
      // two facts are independent, so they get independent lanes.
      const units = (mySize - 4) < (theirSize - 4) ? (mySize - 4) : (theirSize - 4);
      TableFixedPush(plan, TableFixedOpText, theirAt, at, units, auxAt, guard, arg, dst[row + TableFixedDstArg]);
      break;
    }
    default: {
      if (theirSize === mySize) {
        TableFixedPush(plan, TableFixedOpCopy, theirAt, at, mySize, 0, guard, arg, 0);
      } else if (theirSize < mySize && mySize <= 8) {
        TableFixedPush(plan, TableFixedOpWiden, theirAt, at, theirSize, 0, guard, arg, mySize & 0xff);
      } else {
        report.kindMismatch++;
      }
      break;
    }
  }
}

// THE COALESCER, and it is the only optimization a plan compiler performs: two
// neighbouring COPY entries whose source and destination both advance together
// are one entry. It is performed identically on both sides.
function TableFixedCoalesce(plan, from) {
  const e = plan.entries;
  let out = from | 0;
  for (let i = out; i < plan.count; i++) {
    const b = i * TableFixedLanes;
    if (out > (from | 0)) {
      const p = (out - 1) * TableFixedLanes;
      if (e[p + TableFixedLaneOp] === TableFixedOpCopy && e[b + TableFixedLaneOp] === TableFixedOpCopy &&
          e[p + TableFixedLaneGuard] === e[b + TableFixedLaneGuard] && e[p + TableFixedLaneArg] === e[b + TableFixedLaneArg] &&
          e[p + TableFixedLaneArgW] === e[b + TableFixedLaneArgW] &&
          e[p + TableFixedLaneSrc] + e[p + TableFixedLaneSize] === e[b + TableFixedLaneSrc] &&
          e[p + TableFixedLaneDst] + e[p + TableFixedLaneSize] === e[b + TableFixedLaneDst]) {
        e[p + TableFixedLaneSize] += e[b + TableFixedLaneSize];
        continue;
      }
    }
    const o = out * TableFixedLanes;
    for (let k = 0; k < TableFixedLanes; k++) { e[o + k] = e[b + k]; }
    out++;
  }
  plan.count = out;
}

// TableFixedCompile builds the plan for ANOTHER writer's layout against my own,
// and answers how many entries it wrote, or -1 when it did not fit.
// ---- THE LINEAGE, AS STATIC DATA (docs/FIXED-FORM-ALGORITHM.md §5) ---------
//
// A fixed table reads BACKWARD and never forward. A file is matched on the eight
// bytes of its header's hash against the lineage the BUILD laid down, and the
// layout it carries is held to a BYTE COMPARISON against the bytes the lock
// recorded — never walked. A hash the lineage does not hold is layout_newer
// (ship the reader); a hash it holds below the floor is layout_unsupported
// (upgrade the client). Those are the operator's two distinct answers, and
// NOTHING PARSES A STRANGER'S LAYOUT ON ANY PATH.

// TableFixedKnownLayout is ONE locked layout, and its members are §5.9 #19's
// four IN THAT ORDER: the hash a file is matched on, the layout bytes verbatim,
// the byte length riding BESIDE them, and the RECORD SIZE taken from the lock and
// never from the file.
//
// THE HASH IS TWO UINT32 LANES and not one member, which is this language's only
// divergence from that row's spelling: JavaScript has no sixty-four-bit integer
// without a BigInt, and the same hash is compared once per RECORD in the read
// loop, where an allocation per record is the cost §3.4 already refused.
export class TableFixedKnownLayout {
  constructor(hashLo, hashHi, layout, layoutBytes, recordBytes) {
    this.hashLo = hashLo | 0;
    this.hashHi = hashHi | 0;
    this.layout = layout;
    this.layoutBytes = layoutBytes | 0;
    this.recordBytes = recordBytes | 0;
  }
}

// TableFixedDecodeLayout turns a KNOWN layout's base64 constant into its bytes,
// ONCE AT MODULE LOAD and off every load path. The bill's §11 cost is the
// bundle: a lineage grows forever — a retired entry stays in it — and a byte
// array literal is six source bytes per wire byte where base64 is four per
// three.
export function TableFixedDecodeLayout(text) {
  const raw = atob(text);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) { out[i] = raw.charCodeAt(i); }
  return out;
}

// TableFixedSelect is §5.3's step 5: the FIRST index whose wire hash is the
// file's, or -1. It is the only thing a file is matched on.
export function TableFixedSelect(known, hashLo, hashHi) {
  for (let i = 0; i < known.length; i++) {
    if ((known[i].hashLo >>> 0) === hashLo && (known[i].hashHi >>> 0) === hashHi) { return i; }
  }
  return -1;
}

// TableFixedRefuseHash is the two refusals that report THE FILE'S hash (§5.3,
// §5.9 #7, #15). REFUSE is total: no counter moves and not one destination byte
// is written, the prefill included.
export function TableFixedRefuseHash(report, refusal, hashLo, hashHi) {
  report.refused = refusal;
  report.layoutHash = (BigInt(hashHi >>> 0) << 32n) | BigInt(hashLo >>> 0);
  return -1;
}

// TableFixedLineagePlans lays ONE PLAN PER LINEAGE ENTRY down from THE LOCK'S
// OWN BYTES, at MODULE LOAD — which is build time for this page and conforming
// (§5.9 #3): the bytes came from the lock, the walk happens once per process, off
// every load path, and a plan that will not build is a build-time answer and
// never a refusal at the first file that needs it. What §5.8 row 3 forbids is the
// other thing — compiling a plan FROM A FILE'S bytes when a load asks for it, and
// keeping it in a cache a load can miss.
//
// THE SIZE IS DISCOVERED BY GROWING (§5.9 #4, #21): this language has an
// allocator, so the build retries at four times the room up to 2^18 entries
// rather than stating a formula, and an entry whose plan exceeds that records
// plan_too_large ON THAT ENTRY, by name, for the day a file selects it.
export function TableFixedLineagePlans(known, ownLo, ownHi, myLayout, myDst, imageBytes) {
  const out = [];
  for (let i = 0; i < known.length; i++) {
    const k = known[i];
    if ((k.hashLo >>> 0) === (ownLo >>> 0) && (k.hashHi >>> 0) === (ownHi >>> 0)) {
      out.push(null); // the IDENTITY entry: the baked plan answers it
      continue;
    }
    const theirs = new TableFixedLayoutView();
    if (!TableFixedParseLayout(k.layout, 0, k.layoutBytes, theirs)) {
      // A LINEAGE ENTRY THAT IS NOT A LAYOUT IS A BUG IN THE LOCK and the build
      // fails (§5.9 #8); the generator holds that. Where the entries arrived at
      // run time the reader still owes a NAME rather than a throw, so the entry
      // carries layout_malformed and LOAD refuses by it.
      const bad = new TableFixedPlan(1, imageBytes, 1);
      bad.why = TableFixedRefusal.LayoutMalformed;
      out.push(bad);
      continue;
    }
    let lane = null;
    for (let room = 256; room <= (1 << 18); room *= 4) {
      const plan = new TableFixedPlan(room, imageBytes, room * 8);
      const census = new TableFixedReport();
      const made = TableFixedCompile(theirs, myLayout, myDst, plan, census);
      if (made < 0) { continue; }
      plan.recordBytes = k.recordBytes;
      // THE CENSUS IS THE PLAN'S OWN NUMBER, fixed when the plan was built, and
      // the load carries it onto the report ONCE, AFTER the record loop, on a
      // read that RETURNS (§5.4, §5.9 #6).
      plan.unknown = census.unknown;
      plan.kindMismatch = census.kindMismatch;
      plan.ready = true;
      lane = plan;
      break;
    }
    if (lane === null) {
      lane = new TableFixedPlan(1, imageBytes, 1);
      lane.why = TableFixedRefusal.PlanTooLarge;
    }
    out.push(lane);
  }
  return out;
}

export function TableFixedCompile(theirs, myLayout, myDst, plan, report) {
  const mine = new TableFixedLayoutView();
  if (!TableFixedParseLayout(myLayout, 0, myLayout.length, mine)) { return -1; }
  plan.count = 0;
  plan.remapUsed = 0;
  plan.overflow = false;
  plan.argw = 1;
  // PASS 1, UNGUARDED, COUNTING THE CENSUS. PASS 2, GUARDED, COUNTING NOTHING
  // (§5.2 PLAN): the census is once per peer, so a second walk of the same pairs
  // must not count them twice.
  plan.pass = 0;
  TableFixedMatchChildren(plan, theirs, 0, 0, mine, 0, myDst, 0, TableFixedNoGuard, 0, report);
  TableFixedCoalesce(plan, 0);
  plan.split = plan.count;
  plan.pass = 1;
  const quiet = new TableFixedReport();
  TableFixedMatchChildren(plan, theirs, 0, 0, mine, 0, myDst, 0, TableFixedNoGuard, 0, quiet);
  TableFixedCoalesce(plan, plan.split);
  plan.pass = 0;
  if (plan.overflow) { return -1; }
  return plan.count;
}

// FixedTable's storage. Preallocated in the constructor and never replaced: a
// read FILLS one of these, exactly as Read<Name>Flat fills a packet class.
export class FixedTable {
  constructor() {
    this.Value = new BenchMixed();
  }
}

// InitFixedTable restores fresh construction values in place, preserving storage.
export function InitFixedTable(value) {
  InitBenchMixed(value.Value);
}

// MixedEntity's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function MixedEntityFixedWriteBody(view, at, value) {
  view.setUint32(at, value.EntityId, true);
  view.setInt32(at + 4, value.PosX, true);
  view.setInt32(at + 8, value.PosY, true);
  view.setInt32(at + 12, value.PosZ, true);
  view.setUint32(at + 16, value.Yaw, true);
  view.setUint32(at + 20, value.Pitch, true);
  view.setInt32(at + 24, value.VelX, true);
  view.setInt32(at + 28, value.VelY, true);
  view.setInt32(at + 32, value.VelZ, true);
  view.setInt32(at + 36, value.Health, true);
  view.setUint8(at + 40, value.Weapon);
  view.setBigUint64(at + 41, value.Damage, true);
  view.setUint8(at + 49, value.Moving ? 1 : 0);
  view.setUint8(at + 50, value.Firing ? 1 : 0);
}

// MixedEntity's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function MixedEntityFixedDecode(value, view, at, report) {
  value.EntityId = view.getUint32(at, true);
  if (value.EntityId > 4095) { value.EntityId = 4095; report.clamped++; }
  value.PosX = view.getInt32(at + 4, true);
  if (value.PosX < -16383) { value.PosX = -16383; report.clamped++; } else if (value.PosX > 16383) { value.PosX = 16383; report.clamped++; }
  value.PosY = view.getInt32(at + 8, true);
  if (value.PosY < -16383) { value.PosY = -16383; report.clamped++; } else if (value.PosY > 16383) { value.PosY = 16383; report.clamped++; }
  value.PosZ = view.getInt32(at + 12, true);
  if (value.PosZ < -16383) { value.PosZ = -16383; report.clamped++; } else if (value.PosZ > 16383) { value.PosZ = 16383; report.clamped++; }
  value.Yaw = view.getUint32(at + 16, true);
  if (value.Yaw > 511) { value.Yaw = 511; report.clamped++; }
  value.Pitch = view.getUint32(at + 20, true);
  if (value.Pitch > 511) { value.Pitch = 511; report.clamped++; }
  value.VelX = view.getInt32(at + 24, true);
  if (value.VelX < -2048) { value.VelX = -2048; report.clamped++; } else if (value.VelX > 2047) { value.VelX = 2047; report.clamped++; }
  value.VelY = view.getInt32(at + 28, true);
  if (value.VelY < -2048) { value.VelY = -2048; report.clamped++; } else if (value.VelY > 2047) { value.VelY = 2047; report.clamped++; }
  value.VelZ = view.getInt32(at + 32, true);
  if (value.VelZ < -2048) { value.VelZ = -2048; report.clamped++; } else if (value.VelZ > 2047) { value.VelZ = 2047; report.clamped++; }
  value.Health = view.getInt32(at + 36, true);
  if (value.Health < 0) { value.Health = 0; report.clamped++; } else if (value.Health > 1000) { value.Health = 1000; report.clamped++; }
  value.Weapon = view.getUint8(at + 40);
  if (value.Weapon > 15) { value.Weapon = 0; report.clamped++; }
  value.Damage = view.getBigUint64(at + 41, true);
  value.Moving = view.getUint8(at + 49) !== 0;
  value.Firing = view.getUint8(at + 50) !== 0;
}

// MixedStat's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function MixedStatFixedWriteBody(view, at, value) {
  view.setUint32(at, value.StatId, true);
  view.setInt32(at + 4, value.Delta, true);
}

// MixedStat's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function MixedStatFixedDecode(value, view, at, report) {
  value.StatId = view.getUint32(at, true);
  if (value.StatId > 255) { value.StatId = 255; report.clamped++; }
  value.Delta = view.getInt32(at + 4, true);
  if (value.Delta < -512) { value.Delta = -512; report.clamped++; } else if (value.Delta > 511) { value.Delta = 511; report.clamped++; }
}

// MixedHitEvent's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function MixedHitEventFixedWriteBody(view, at, value) {
  view.setUint32(at, value.TargetId, true);
  view.setInt32(at + 4, value.Damage, true);
  view.setInt32(at + 8, value.HitKind, true);
  view.setUint8(at + 12, value.Crit ? 1 : 0);
}

// MixedHitEvent's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function MixedHitEventFixedDecode(value, view, at, report) {
  value.TargetId = view.getUint32(at, true);
  if (value.TargetId > 4095) { value.TargetId = 4095; report.clamped++; }
  value.Damage = view.getInt32(at + 4, true);
  if (value.Damage < 0) { value.Damage = 0; report.clamped++; } else if (value.Damage > 4095) { value.Damage = 4095; report.clamped++; }
  value.HitKind = view.getInt32(at + 8, true);
  if (value.HitKind < 0) { value.HitKind = 0; report.clamped++; } else if (value.HitKind > 7) { value.HitKind = 7; report.clamped++; }
  value.Crit = view.getUint8(at + 12) !== 0;
}

// MixedChatEvent's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function MixedChatEventFixedWriteBody(view, at, value) {
  view.setInt32(at, value.Channel, true);
  view.setUint32(at + 4, value.Speaker, true);
}

// MixedChatEvent's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function MixedChatEventFixedDecode(value, view, at, report) {
  value.Channel = view.getInt32(at, true);
  if (value.Channel < 0) { value.Channel = 0; report.clamped++; } else if (value.Channel > 3) { value.Channel = 3; report.clamped++; }
  value.Speaker = view.getUint32(at + 4, true);
  if (value.Speaker > 4095) { value.Speaker = 4095; report.clamped++; }
}

// MixedPickupEvent's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function MixedPickupEventFixedWriteBody(view, at, value) {
  view.setUint32(at, value.ItemId, true);
  view.setInt32(at + 4, value.Amount, true);
}

// MixedPickupEvent's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function MixedPickupEventFixedDecode(value, view, at, report) {
  value.ItemId = view.getUint32(at, true);
  if (value.ItemId > 1023) { value.ItemId = 1023; report.clamped++; }
  value.Amount = view.getInt32(at + 4, true);
  if (value.Amount < 0) { value.Amount = 0; report.clamped++; } else if (value.Amount > 255) { value.Amount = 255; report.clamped++; }
}

// BenchMixed's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function BenchMixedFixedWriteBody(view, at, value) {
  view.setUint32(at, value.Sequence, true);
  view.setInt32(at + 4, value.AckSequence, true);
  view.setUint32(at + 8, value.AckBits, true);
  view.setBigUint64(at + 12, value.SessionId, true);
  view.setUint32(at + 20, value.ClientId, true);
  view.setBigUint64(at + 24, value.Nonce, true);
  view.setBigInt64(at + 32, value.WorldTime, true);
  view.setBigUint64(at + 40, value.FrameTick, true);
  view.setInt32(at + 48, value.ServerTime, true);
  view.setInt32(at + 52, value.EntitiesCount, true);
  for (let i = 0; i < value.EntitiesCount; i++) {
    MixedEntityFixedWriteBody(view, at + 56 + i * 51, value.Entities[i]);
  }
  view.setInt32(at + 464, value.StatsCount, true);
  for (let i = 0; i < value.StatsCount; i++) {
    MixedStatFixedWriteBody(view, at + 468 + i * 8, value.Stats[i]);
  }
  view.setUint8(at + 1108, value.GameEvent.Type);
  switch (value.GameEvent.Type) {
    case 1: {
      MixedHitEventFixedWriteBody(view, at + 1109, value.GameEvent.Hit);
      break;
    }
    case 2: {
      MixedChatEventFixedWriteBody(view, at + 1109, value.GameEvent.Chat);
      break;
    }
    case 3: {
      MixedPickupEventFixedWriteBody(view, at + 1109, value.GameEvent.Pickup);
      break;
    }
    default: break;
  }
  for (let i = 0; i < 4; i++) {
    view.setUint8(at + 1122 + i * 1, value.Loadout[i]);
  }
  view.setInt32(at + 1126, value.PlayerNameLength, true);
  for (let i = 0; i < value.PlayerNameLength; i++) { view.setUint8(at + 1130 + i, value.PlayerName[i]); }
  view.setInt32(at + 1145, value.PayloadLength, true);
  for (let i = 0; i < value.PayloadLength; i++) { view.setUint8(at + 1149 + i, value.Payload[i]); }
  view.setFloat32(at + 1165, value.AimX, true);
  view.setFloat32(at + 1169, value.AimY, true);
  view.setFloat32(at + 1173, value.AimZ, true);
  view.setFloat32(at + 1177, value.Recoil, true);
  view.setFloat64(at + 1181, value.Drift, true);
  view.setBigUint64(at + 1189, BigInt.asUintN(64, value.WideKey), true);
  view.setBigUint64(at + 1189 + 8, BigInt.asUintN(64, value.WideKey >> 64n), true);
  view.setBigUint64(at + 1205, BigInt.asUintN(64, value.Flux), true);
  view.setBigUint64(at + 1205 + 8, BigInt.asUintN(64, value.Flux >> 64n), true);
  view.setUint16(at + 1221, value.Ping, true);
  view.setUint32(at + 1223, value.CrcHint, true);
  view.setUint8(at + 1227, value.HasExtra ? 1 : 0);
  view.setInt32(at + 1228, value.Extra, true);
  view.setInt32(at + 1232, value.IdleTicks, true);
}

// BenchMixed's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function BenchMixedFixedDecode(value, view, at, report) {
  value.Sequence = view.getUint32(at, true);
  if (value.Sequence > 65535) { value.Sequence = 65535; report.clamped++; }
  value.AckSequence = view.getInt32(at + 4, true);
  if (value.AckSequence < 0) { value.AckSequence = 0; report.clamped++; } else if (value.AckSequence > 65535) { value.AckSequence = 65535; report.clamped++; }
  value.AckBits = view.getUint32(at + 8, true);
  value.SessionId = view.getBigUint64(at + 12, true);
  value.ClientId = view.getUint32(at + 20, true);
  value.Nonce = view.getBigUint64(at + 24, true);
  value.WorldTime = view.getBigInt64(at + 32, true);
  if (value.WorldTime < -1000000000000n) { value.WorldTime = -1000000000000n; report.clamped++; } else if (value.WorldTime > 1000000000000n) { value.WorldTime = 1000000000000n; report.clamped++; }
  value.FrameTick = view.getBigUint64(at + 40, true);
  if (value.FrameTick > 281474976710655n) { value.FrameTick = 281474976710655n; report.clamped++; }
  value.ServerTime = view.getInt32(at + 48, true);
  if (value.ServerTime < 0) { value.ServerTime = 0; report.clamped++; } else if (value.ServerTime > 16776960) { value.ServerTime = 16776960; report.clamped++; }
  {
    let n = view.getInt32(at + 52, true);
    if (n < 0) { n = 0; report.clamped++; } else if (n > 8) { n = 8; report.clamped++; }
    value.EntitiesCount = n;
  }
  for (let i = 0; i < value.EntitiesCount; i++) {
    MixedEntityFixedDecode(value.Entities[i], view, at + 56 + i * 51, report);
  }
  {
    let n = view.getInt32(at + 464, true);
    if (n < 0) { n = 0; report.clamped++; } else if (n > 80) { n = 80; report.clamped++; }
    value.StatsCount = n;
  }
  for (let i = 0; i < value.StatsCount; i++) {
    MixedStatFixedDecode(value.Stats[i], view, at + 468 + i * 8, report);
  }
  value.GameEvent.Type = view.getUint8(at + 1108);
  if (value.GameEvent.Type > 3) { value.GameEvent.Type = 0; report.clamped++; }
  switch (value.GameEvent.Type) {
    case 1: {
      MixedHitEventFixedDecode(value.GameEvent.Hit, view, at + 1109, report);
      break;
    }
    case 2: {
      MixedChatEventFixedDecode(value.GameEvent.Chat, view, at + 1109, report);
      break;
    }
    case 3: {
      MixedPickupEventFixedDecode(value.GameEvent.Pickup, view, at + 1109, report);
      break;
    }
    default: break;
  }
  for (let i = 0; i < 4; i++) {
    value.Loadout[i] = view.getUint8(at + 1122 + i * 1);
  }
  {
    let n = view.getInt32(at + 1126, true);
    if (n < 0) { n = 0; report.clamped++; } else if (n > 15) { n = 15; report.clamped++; }
    value.PlayerNameLength = n;
  }
  for (let i = 0; i < 15; i++) { value.PlayerName[i] = view.getUint8(at + 1130 + i); }
  {
    let n = view.getInt32(at + 1145, true);
    if (n < 0) { n = 0; report.clamped++; } else if (n > 16) { n = 16; report.clamped++; }
    value.PayloadLength = n;
  }
  for (let i = 0; i < 16; i++) { value.Payload[i] = view.getUint8(at + 1149 + i); }
  value.AimX = view.getFloat32(at + 1165, true);
  value.AimY = view.getFloat32(at + 1169, true);
  value.AimZ = view.getFloat32(at + 1173, true);
  value.Recoil = view.getFloat32(at + 1177, true);
  value.Drift = view.getFloat64(at + 1181, true);
  value.WideKey = view.getBigUint64(at + 1189, true) | (view.getBigUint64(at + 1189 + 8, true) << 64n);
  value.Flux = view.getBigUint64(at + 1205, true) | (view.getBigUint64(at + 1205 + 8, true) << 64n);
  value.Flux = BigInt.asIntN(128, value.Flux);
  if (value.Flux < -1267650600228229401496703205376n) { value.Flux = -1267650600228229401496703205376n; report.clamped++; } else if (value.Flux > 1267650600228229401496703205376n) { value.Flux = 1267650600228229401496703205376n; report.clamped++; }
  value.Ping = view.getUint16(at + 1221, true);
  if (value.Ping > 64000) { value.Ping = 64000; report.clamped++; }
  value.CrcHint = view.getUint32(at + 1223, true);
  if (value.CrcHint > 16777215) { value.CrcHint = 16777215; report.clamped++; }
  value.HasExtra = view.getUint8(at + 1227) !== 0;
  value.Extra = view.getInt32(at + 1228, true);
  if (value.Extra < 0) { value.Extra = 0; report.clamped++; } else if (value.Extra > 255) { value.Extra = 255; report.clamped++; }
  value.IdleTicks = view.getInt32(at + 1232, true);
  if (value.IdleTicks < 0) { value.IdleTicks = 0; report.clamped++; } else if (value.IdleTicks > 15) { value.IdleTicks = 15; report.clamped++; }
}

// FixedTable's stores. Every offset is a constant of the type and nothing is
// measured: on this form MeasureBody is a constant, not a walk.
export function FixedTableFixedWriteBody(view, at, value) {
  BenchMixedFixedWriteBody(view, at, value.Value);
}

// FixedTable's loads, out of the reader's own image and into the value the
// caller handed in — filled, never returned, exactly as Read<Name>Flat is.
export function FixedTableFixedDecode(value, view, at, report) {
  BenchMixedFixedDecode(value.Value, view, at, report);
}

